```dart
import 'glasses_frame.dart';

/// Dart builders for glasses BLE commands. See `native_app/inventory/05-glasses-protocol-map.md`.
class GlassesOrder {
  GlassesOrder._();

  static const glassesId = 0x34;
  static const wifiId = 0x33;

  /// Device control: photo.
  static const controlTypePhoto = 1;

  /// Device control: audio recording.
  static const controlTypeAudio = 2;

  /// Device control: video recording.
  static const controlTypeVideo = 3;

  /// Recording max duration. [type] 0 = video, 1 = audio.
  static List<int> sendRecordMaxTime({required int type, required int maxTime}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x01,
      payload: [type, maxTime ~/ 256, maxTime % 256],
    );
  }

  /// Key mapping for a physical button.
  static List<int> sendKeyDefine({
    required int keyId,
    required int updateType,
    required int click,
    required int doubleClick,
    required int tripleClick,
    required int longPress2s,
    required int longPress3s,
    required int longPress4s,
    required int longPress5s,
  }) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x02,
      payload: [
        keyId,
        updateType,
        click,
        doubleClick,
        tripleClick,
        longPress2s,
        longPress3s,
        longPress4s,
        longPress5s,
      ],
    );
  }

  /// Volume level 0–100.
  static List<int> sendVolume(int volume) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x03,
      payload: [volume.clamp(0, 100)],
    );
  }

  /// Voice wakeup on/off.
  static List<int> switchWakeup({required bool isOpen}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x04,
      payload: [isOpen ? 0x01 : 0x00],
    );
  }

  /// WiFi scan on/off.
  static List<int> switchWifiScan({required bool isOpen}) {
    if (isOpen) {
      return GlassesFrame.build(id: wifiId, subId: 0x09, payload: [0x00]);
    }
    return [0xEA, 0x00, 0x03, 0x00, wifiId, 0x0C];
  }

  /// Device control: [type] uses [controlTypePhoto|Audio|Video]; [action] 0 off, 1 on.
  static List<int> sendDeviceControl({
    required int type,
    required int action,
  }) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x11,
      payload: [type, action],
    );
  }

  /// Hall sensor manual/auto mode.
  static List<int> setHallSwitch({required bool isOpen}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x0F,
      payload: [isOpen ? 0x01 : 0x00],
    );
  }

  /// Auto shutdown query (mode 0) or set (mode 1) with [minute].
  static List<int> setAutoShutdown({required int mode, required int minute}) {
    return GlassesFrame.build(
      id: glassesId,
      subId: 0x10,
      payload: [mode, minute],
    );
  }
}
```

