import 'package:core_ble/core_ble.dart';
import 'package:core_permission/core_permission.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

/// Pairing and connection flow for BLE devices.
class DeviceConnectPage extends ConsumerStatefulWidget {
  /// Creates the connect page.
  const DeviceConnectPage({
    super.key,
    this.initialDevice,
    this.deviceSearchRoute = '/device/search',
  });

  /// Pre-selected device from device search.
  final BleDevice? initialDevice;

  /// Route to open BLE device search.
  final String deviceSearchRoute;

  @override
  ConsumerState<DeviceConnectPage> createState() => _DeviceConnectPageState();
}

class _DeviceConnectPageState extends ConsumerState<DeviceConnectPage> {
  late final TextEditingController _deviceIdController;
  var _busy = false;

  @override
  void initState() {
    super.initState();
    _deviceIdController = TextEditingController(
      text: widget.initialDevice?.id ?? '',
    );
  }

  @override
  void dispose() {
    _deviceIdController.dispose();
    super.dispose();
  }

  Future<void> _run(Future<void> Function() action) async {
    setState(() => _busy = true);
    await action();
    if (mounted) {
      setState(() => _busy = false);
    }
  }

  Future<void> _connect() async {
    final deviceId = _deviceIdController.text.trim();
    if (deviceId.isEmpty) {
      return;
    }

    await _run(() async {
      final permissionResult = await BlePermissionGate.ensureScanPermissions(
        ref.read(permissionServiceProvider),
      );
      if (permissionResult case Failure()) {
        return;
      }

      await ref.read(bleSessionProvider.notifier).connect(
            deviceId: deviceId,
            deviceName: widget.initialDevice?.displayName,
          );
    });
  }

  Future<void> _disconnect() async {
    await _run(() async {
      await ref.read(bleSessionProvider.notifier).disconnect();
    });
  }

  @override
  Widget build(BuildContext context) {
    ref.listen<bool>(
      bleSessionProvider.select((state) => state.isConnected),
      (previous, connected) {
        if (connected && previous != true && context.mounted) {
          context.pop();
        }
      },
    );

    final isConnected = ref.watch(
      bleSessionProvider.select((state) => state.isConnected),
    );
    final canEdit = !isConnected && !_busy;
    final device = widget.initialDevice;

    return BleSessionListener(
      child: Scaffold(
        appBar: AppBar(title: const Text('Connect Device')),
        body: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            Text(
              'Select a device from search or paste its BLE id below.',
              style: Theme.of(context).textTheme.bodyMedium,
            ),
            if (device != null) ...[
              const SizedBox(height: 12),
              Card(
                child: ListTile(
                  leading: const Icon(Icons.bluetooth),
                  title: Text(device.displayName),
                  subtitle: Text(device.id),
                  trailing: Text('${device.rssi} dBm'),
                ),
              ),
            ],
            const SizedBox(height: 16),
            TextField(
              controller: _deviceIdController,
              decoration: const InputDecoration(
                labelText: 'Device ID',
                border: OutlineInputBorder(),
              ),
              enabled: canEdit,
            ),
            const SizedBox(height: 12),
            FilledButton.icon(
              onPressed: canEdit ? _connect : null,
              icon: const Icon(Icons.link),
              label: const Text('Connect'),
            ),
            if (isConnected) ...[
              const SizedBox(height: 8),
              OutlinedButton.icon(
                onPressed: _busy ? null : _disconnect,
                icon: const Icon(Icons.link_off),
                label: const Text('Disconnect'),
              ),
            ],
            const SizedBox(height: 16),
            OutlinedButton.icon(
              onPressed: () => context.push(widget.deviceSearchRoute),
              icon: const Icon(Icons.bluetooth_searching),
              label: const Text('Open device search'),
            ),
          ],
        ),
      ),
    );
  }
}
```

