import 'device_settings_state.dart';

/// Device settings state.
final deviceSettingsControllerProvider =
    NotifierProvider<DeviceSettingsController, DeviceSettingsState>(
  DeviceSettingsController.new,
);

/// Applies device settings via protocol commands.
class DeviceSettingsController extends Notifier<DeviceSettingsState> {
  GlassesCommandSender get _sender => GlassesCommandSender(
        session: ref.read(bleSessionProvider.notifier),
        config: ref.read(glassesTransportConfigProvider),
      );

  @override
  DeviceSettingsState build() {
    ref.listen<bool>(
      bleSessionProvider.select((session) => session.isConnected),
      (previous, connected) {
        if (previous == true && connected == false) {
          state = const DeviceSettingsState();
        }
      },
    );
    return const DeviceSettingsState();
  }

  /// Sets device volume via protocol.
  Future<Result<void>> setVolume(int volume) async {
    final sendResult = await _sender.setVolume(volume);
    return sendResult.fold(
      onSuccess: (_) {
        state = state.copyWith(volume: volume, clearError: true);
        return const Result.success(null);
      },
      onFailure: (error) {
        state = state.copyWith(lastError: error.message);
        return Result.failure(error);
      },
    );
  }

  /// Toggles WiFi scan via protocol.
  Future<Result<void>> setWifiScanEnabled(bool enabled) async {
    final sendResult = await _sender.setWifiScan(enabled: enabled);
    return sendResult.fold(
      onSuccess: (_) {
        state = state.copyWith(wifiScanEnabled: enabled, clearError: true);
        return const Result.success(null);
      },
      onFailure: (error) {
        state = state.copyWith(lastError: error.message);
        return Result.failure(error);
      },
    );
  }
}
