  const DeviceHomeShell({
    required this.body,
    required this.connectRoute,
    required this.settingsRoute,
    this.deviceSearchRoute = '/device/search',
    this.interpretationRoute,
    super.key,
  });

  /// App-specific device home content placed under overlays.
  final Widget body;

  /// Route to open BLE connect flow.
  final String connectRoute;

  /// Route to open device settings.
  final String settingsRoute;

  /// Route passed to quick actions for BLE search.
  final String deviceSearchRoute;

  /// Optional route to simultaneous interpretation.
  final String? interpretationRoute;

  static const _horizontalInset = 12.0;
  static const _fabBottomOffset = 88.0;

