/// Root widget. ProviderScope wraps the app for Riverpod DI.
class GlassesApp extends StatelessWidget {
  const GlassesApp({super.key});

  @override
  Widget build(BuildContext context) {
    return ProviderScope(
      overrides: [
        bleServiceProvider.overrideWithValue(FlutterBlueBleService()),
        permissionServiceProvider.overrideWithValue(
          const PermissionHandlerService(),
        ),
        onDeviceSelectedProvider.overrideWith(
          (ref) => (device) {
            final context = rootNavigatorKey.currentContext;
            if (context != null && context.mounted) {
              context.push(DeviceConnectRoutePaths.connect, extra: device);
            }
          },
        ),
      ],
      child: MaterialApp.router(
        title: 'Glasses App',
        theme: appTheme,
        routerConfig: appRouter,
      ),
    );
  }
}
