final _featureRoutes = <RouteGroup>[
  deviceSearchRoutes,
  deviceConnectRoutes(deviceSearchRoute: DeviceSearchRoutePaths.search),
  deviceSettingsRoutes(),
  interpretationRoutes(),
];

List<RouteBase> _buildRoutes() {
  return [
    for (final group in _featureRoutes) ...group.routes,
    GoRoute(
      path: '/',
      builder: (context, state) => const HomePage(),
    ),
  ];
}

